pub fn append_array(mut a: Vec<i32>, mut b: Vec<i32>) -> Vec<i32> {
    // Ensure length/capacity computation doesn't overflow usize.
    let total_len = a
        .len()
        .checked_add(b.len())
        .expect("vector length overflow");

    // Build result by moving elements in order: a then b.
    let mut c = Vec::with_capacity(total_len);
    c.append(&mut a); // moves all elements of a into c (preserves order)
    c.append(&mut b); // then moves all elements of b into c (preserves order)

    // c.len() == total_len holds because append moves exactly all elements.
    c
}